const GRAPHICS_ARIA: &str = "../../packages/aria-data/graphics-aria-1-0.json";
const DPUB_ARIA: &str = "../../packages/aria-data/dpub-aria-1-1.json";

const ISO_COUNTRIES: &[&str] = &[
