pub struct UseValidAriaValuesState {
    /// The attribute name exactly as written in source (case preserved).
    attribute_name: String,
    range: TextRange,
    property_type: AriaValueType,
}

impl Rule for UseValidAriaValues {
    type Query = Ast<HtmlAttribute>;
    type State = UseValidAriaValuesState;
    type Signals = Option<Self::State>;
    type Options = UseValidAriaValuesOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
        let name_token = node.name().ok()?.value_token().ok()?;
        let attribute_name = name_token.text_trimmed();

        let source_type = ctx.source_type::<HtmlFileSource>();

        // ARIA attribute names are case-insensitive in HTML documents, but
        // case-sensitive in component templates (Astro, Svelte, Vue).
        let aria_property = if source_type.is_html() {
            AriaAttribute::from_str(&attribute_name.to_ascii_lowercase()).ok()?
        } else {
            AriaAttribute::from_str(attribute_name).ok()?
        };

        // A valueless ARIA attribute (e.g. `<div aria-hidden>`) is treated as
        // having the value `true`. When an initializer is present but the value
        // is not a static string (e.g. a dynamic expression), the attribute is
        // skipped because its value cannot be validated statically.
        let value = match node.initializer() {
            None => "true".to_string(),
            Some(initializer) => initializer.value().ok()?.string_value()?.text().to_string(),
        };

        let property_type = aria_property.value_type();
        if property_type.contains(&value) {
            return None;
        }

        Some(UseValidAriaValuesState {
            attribute_name: attribute_name.to_string(),
            range: node.range(),
            property_type,
        })
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        let attribute_name = state.attribute_name.as_str();
        let diagnostic = RuleDiagnostic::new(
            rule_category!(),
            state.range,
            markup! {
                "The value of the ARIA attribute "<Emphasis>{attribute_name}</Emphasis>" is not correct."
            },
        );

        let diagnostic = match state.property_type {
            AriaValueType::Boolean | AriaValueType::OptionalBoolean => diagnostic.footer_list(
                markup! {
                    "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property are:"
                },
                ["undefined", "false", "true"],
            ),
            AriaValueType::Tristate => diagnostic.footer_list(
                markup! {
                    "The only supported values for the "<Emphasis>{attribute_name}</Emphasis>" property are:"
                },
                ["false", "true", "mixed"],
            ),
            AriaValueType::Integer | AriaValueType::Number => diagnostic.note(markup! {
                "The only supported value is a number."
            }),
            AriaValueType::IdReference | AriaValueType::IdReferenceList => {
                diagnostic.note(markup! {
                    "The only supported value is a space-separated list of HTML identifiers."
                })
            }
            AriaValueType::Token(tokens) | AriaValueType::TokenList(tokens) => diagnostic
                .footer_list(
                    markup! {
                        "The only supported value for the "<Emphasis>{attribute_name}</Emphasis>" property is one of the following:"
                    },
                    tokens,
                ),
            AriaValueType::String => diagnostic.note(markup! {
                "The only supported value is text."
            }),
        };

        Some(diagnostic.note(markup! {
            "Use a valid value for the "<Emphasis>{attribute_name}</Emphasis>" attribute according to the WAI-ARIA specification."
        }))
    }
